import {STORAGE,COURSES,WORDS,text,validate} from './curriculum-model.js';
const lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ko',t=(ko,en)=>lang==='en'?en:ko,w=key=>text(WORDS[key]||key,lang),$=id=>document.getElementById(id);document.documentElement.lang=lang;let data;
const el=(tag,parent,value)=>{const e=document.createElement(tag);if(value!==undefined)e.textContent=value;parent.append(e);return e};
for(const [id,label,href]of [['lab',t('실험실','Laboratory'),'index.html'],['guide',w('guide'),'guide.html'],['legacy',t('이전 중등 기록','Previous middle-school records'),'teacher-legacy.html']]){$(id).textContent=label;$(id).href=href+'?lang='+lang}
$('title').textContent=t('과정별 실험 기록 검토','Review records by course');$('intro').textContent=t('브라우저 기록을 불러오거나 학생이 저장한 JSON 파일을 선택하세요. 과정과 실험별로 조건·측정값·설명을 검토합니다.','Load browser records or a saved student JSON file. Review conditions, measurements and explanations separately by course and experiment.');$('reload').textContent=t('브라우저 기록 불러오기','Load browser records');$('import-label').textContent=t('기록 파일 선택 ','Choose record file ');$('import').setAttribute('aria-label',t('과정별 실험 기록 파일','Course record file'));$('export').textContent=w('export');$('print').textContent=t('인쇄','Print');$('scope').textContent=t('자동 점수나 성취 등급을 매기지 않습니다. 조건 하나를 바꾸어 비교했는지, 측정값을 근거로 설명했는지 확인하세요. 미실시 실험과 작성하지 않은 설명을 구분합니다. 이름·학번은 수집하지 않습니다. 파일을 불러와도 실험실의 브라우저 기록은 덮어쓰지 않습니다.','No automatic score or achievement grade. Check variable control and evidence-based explanations. Unattempted experiments and missing explanations are marked. No names or IDs are collected. Importing does not overwrite laboratory records.');
function metric(m){return w(m.key)+': '+(Math.abs(m.value)<1e-8?'0':Number.isInteger(m.value)?m.value:m.value.toFixed(3))+(m.unit?' '+(m.unit==='relative'?t('칸','units'):m.unit):'')}
function render(){const root=$('records');root.replaceChildren();for(const [id,c]of Object.entries(COURSES)){const session=data.courses[id];el('h2',root,text(c.label,lang));for(const a of c.activities){const e=session.experiments[a.id];el('h3',root,text(a.title,lang)+' · '+e.trials.length+' '+w('count'));el('small',root,a.codes.join(', '));if(!e.trials.length){el('p',root,t('미실시','Not attempted'));continue}const wrap=el('div',root);wrap.className='scroll';const table=el('table',wrap),head=el('tr',el('thead',table));for(const key of ['trial','condition','observation'])el('th',head,w(key));const body=el('tbody',table);for(const trial of e.trials){const row=el('tr',body);el('td',row,trial.id);el('td',row,a.controls.map(c=>w(c.label)+': '+(c.options?w(c.options.find(o=>o[0]===trial.inputs[c.key])[1]):trial.inputs[c.key]+' '+c.unit)).join(' · '));el('td',row,trial.result.metrics.map(metric).join(' · '))}el('p',root,text(a.prompt,lang));const note=el('p',root,e.note||w('noNote'));note.className='notes';}}$('export').disabled=false;}
function accept(value){data=validate(value);render();$('status').textContent=t('기록을 불러왔습니다. 측정값은 검증하여 다시 계산했습니다.','Records loaded. Measurements were validated and recomputed.');}
function load(){try{const raw=localStorage.getItem(STORAGE);if(!raw)throw Error('empty');accept(JSON.parse(raw))}catch{$('status').textContent=t('불러올 과정별 기록이 없습니다. 실험하거나 저장한 파일을 선택하세요.','No valid course records found. Run an experiment or select a saved file.');}}
$('reload').onclick=load;$('import').onchange=async()=>{try{const file=$('import').files[0];if(!file)return;if(file.size>8_000_000)throw Error('size');accept(JSON.parse(await file.text()))}catch{$('status').textContent=t('지원하지 않는 파일이거나 기록 형식이 잘못되었습니다. 이전 중등 기록은 위의 별도 화면에서 여세요.','Unsupported or invalid record file. Open previous middle-school records with the link above.');}};
$('export').onclick=()=>{if(!data)return;const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='force-lab-courses-reviewed.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('print').onclick=()=>window.print();load();
